-- A `nextval` default over a free-standing sequence is a default the identity clause
-- refuses.
-- @expect-error: the column already has a default (55000)
-- @expect-message
-- @setup
CREATE SEQUENCE aid_free START WITH 100;
CREATE TABLE aid (c BIGINT NOT NULL DEFAULT nextval('aid_free'), v TEXT);
-- @test
ALTER TABLE aid ALTER COLUMN c ADD GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME aid_named START WITH 40);
